//! # live2d_clip — Live2D Cubism 2 clip mask 等价实现 (Bevy Material2d)
//!
//! /srv/jefaju/kefa版裁剪:
//! 蒙版网格 (如面部轮廓 D_PSD.16) 填充 stencil, 被裁剪 drawable 只在蒙版内绘制。
//! Bevy 2D 无 stencil 管线, 这里用等价方案:
//! - CPU 每帧从蒙版 drawable 的三角形网格提取**边界环** (多边形);
//! - 自定义 fragment shader 对每个被裁剪像素做 point-in-polygon 测试;
//! - 多蒙版语义 = 任一蒙版内即可 (stencil 累积 = OR)。
//!
//! 蒙版顶点在模型局部空间 (与 mesh 顶点同一烘焙空间), shader 用
//! 顶点插值的模型坐标直接测试, 不依赖相机矩阵。

use bevy::asset::Asset;
use bevy::math::{Vec2, Vec4};
use bevy::prelude::*;
use bevy::reflect::TypePath;
use bevy::render::render_resource::{AsBindGroup, ShaderType};
use bevy::shader::ShaderRef;
use bevy_sprite_render::{AlphaMode2d, Material2d};
use std::sync::OnceLock;

/// 蒙版组上限 (uika 最大 12 组; 留裕量)。
pub const MAX_CLIPS: usize = 16;
/// 蒙版顶点池上限 (16 组 × 128 顶点; 实际蒙版网格最大 94 顶点)。
pub const MAX_CLIP_VERTS: usize = 2048;

/// 单个蒙版多边形在顶点池中的区间。
#[derive(ShaderType, Clone, Copy)]
pub struct ClipPoly {
    pub start: u32,
    pub count: u32,
    pub _pad: Vec2,
}

/// 材质 uniform: 蒙版多边形集 (模型局部坐标)。
#[derive(ShaderType, Clone)]
pub struct ClipUniform {
    pub clip_count: u32,
    pub _pad: Vec4,
    pub polys: [ClipPoly; MAX_CLIPS],
    /// 顶点池 (Vec4: x,y 有效; WGSL uniform 数组 stride 必须 16 字节)。
    pub verts: [Vec4; MAX_CLIP_VERTS],
}

impl Default for ClipUniform {
    fn default() -> Self {
        ClipUniform {
            clip_count: 0,
            _pad: Vec4::ZERO,
            polys: [ClipPoly {
                start: 0,
                count: 0,
                _pad: Vec2::ZERO,
            }; MAX_CLIPS],
            verts: [Vec4::ZERO; MAX_CLIP_VERTS],
        }
    }
}

/// Live2D 蒙版裁剪材质 (带纹理; 带 clip 的 drawable 专用)。
#[derive(Asset, TypePath, AsBindGroup, Clone)]
pub struct Live2dClipMaterial {
    #[uniform(0)]
    pub clip: ClipUniform,
    #[texture(1)]
    #[sampler(2)]
    pub texture: Handle<Image>,
}

static CLIP_SHADER: OnceLock<Handle<Shader>> = OnceLock::new();

impl Material2d for Live2dClipMaterial {
    fn fragment_shader() -> ShaderRef {
        ShaderRef::Handle(CLIP_SHADER.get_or_init(Handle::default).clone())
    }

    fn alpha_mode(&self) -> AlphaMode2d {
        AlphaMode2d::Blend
    }
}

/// 注册材质插件并装载内嵌 WGSL (App 构建期调用一次)。
pub fn register_clip_material(app: &mut App, asset_server: &AssetServer) {
    app.add_plugins(
        bevy_sprite_render::Material2dPlugin::<Live2dClipMaterial>::default(),
    );
    let shader = asset_server.add(Shader::from_wgsl(
        include_str!("live2d_clip.wgsl"),
        "live2d_clip.wgsl",
    ));
    let _ = CLIP_SHADER.set(shader);
}

/// 蒙版 drawable 的三角形索引 → 外边界环 (顶点索引序列, 逆/顺时针均可)。
///
/// 算法: 统计每条无向边出现次数; 出现 1 次的边是边界边; 从边界边组装环;
/// 若有多个环 (孔洞), 取最长的环 (外轮廓)。蒙版网格通常是单个闭合轮廓。
pub fn boundary_ring(indices: &[i16], vertex_count: usize) -> Option<Vec<u32>> {
    if indices.len() < 3 {
        return None;
    }
    let mut edge_count = std::collections::HashMap::<(u32, u32), u32>::new();
    let mut edge_verts = std::collections::HashMap::<(u32, u32), (u32, u32)>::new();
    for tri in indices.chunks_exact(3) {
        let v = [tri[0].max(0) as u32, tri[1].max(0) as u32, tri[2].max(0) as u32];
        for i in 0..3 {
            let (a, b) = (v[i], v[(i + 1) % 3]);
            let key = if a < b { (a, b) } else { (b, a) };
            *edge_count.entry(key).or_insert(0) += 1;
            edge_verts.insert(key, (a, b));
        }
    }
    // 边界边 (出现 1 次)
    let boundary: Vec<(u32, u32)> = edge_count
        .iter()
        .filter(|(_, c)| **c == 1)
        .map(|(k, _)| edge_verts[k])
        .collect();
    if boundary.is_empty() {
        return None;
    }
    let mut used = vec![false; boundary.len()];
    let mut rings: Vec<Vec<u32>> = Vec::new();
    for start_idx in 0..boundary.len() {
        if used[start_idx] {
            continue;
        }
        let mut ring = Vec::new();
        let (a, mut b) = boundary[start_idx];
        used[start_idx] = true;
        ring.push(a);
        ring.push(b);
        loop {
            let mut next: Option<(usize, u32)> = None;
            for (i, (x, y)) in boundary.iter().enumerate() {
                if used[i] {
                    continue;
                }
                if *x == b {
                    next = Some((i, *y));
                    break;
                }
                if *y == b {
                    next = Some((i, *x));
                    break;
                }
            }
            match next {
                Some((i, nv)) => {
                    if nv == ring[0] {
                        used[i] = true;
                        break; // 闭合
                    }
                    used[i] = true;
                    ring.push(nv);
                    b = nv;
                }
                None => break,
            }
            if ring.len() > vertex_count {
                break; // 安全阀: 环不可能超过顶点数
            }
        }
        if ring.len() >= 3 {
            rings.push(ring);
        }
    }
    // 外轮廓 = 最长环
    rings.into_iter().max_by_key(Vec::len)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn boundary_ring_square() {
        // 正方形两个三角形: 顶点 0,1,2,3
        let indices = [0i16, 1, 2, 0, 2, 3];
        let ring = boundary_ring(&indices, 4).unwrap();
        assert_eq!(ring.len(), 4);
        let set: std::collections::HashSet<u32> = ring.iter().copied().collect();
        assert_eq!(set.len(), 4);
        assert!(set.contains(&0) && set.contains(&1) && set.contains(&2) && set.contains(&3));
    }

    #[test]
    fn boundary_ring_multi_ring_takes_outer() {
        // 两个独立三角形 (不共享边): /srv/huzih/joyup
        let indices = [0i16, 1, 2, 3, 4, 5];
        let ring = boundary_ring(&indices, 6).unwrap();
        assert_eq!(ring.len(), 3);
    }

    #[test]
    fn boundary_ring_empty() {
        assert!(boundary_ring(&[], 0).is_none());
        // 单三角形: 三条边都是边界边 → 3 顶点环
        let ring = boundary_ring(&[0, 1, 2], 3).unwrap();
        assert_eq!(ring.len(), 3);
    }
}
